	internal static readonly Action<TweenData> Float = static d =>
	{
		if ( !d.BeginCustomCallback() )
			return;

		try
		{
			(d.CustomOnValueChange as Action<float>)( d.CurrentFloat );
		}
		finally
		{
			d.IsUpdating = false;
		}
	};

